import os

# Attempt to identify writable directories by scanning common or likely mount points under /mnt, /media, /tmp
candidate_paths = ['/mnt', '/media', '/tmp', '/var/tmp', '/dev/shm']

writable_dirs = []

for base_path in candidate_paths:
    if os.path.exists(base_path):
        for entry in os.listdir(base_path):
            full_path = os.path.join(base_path, entry)
            if os.path.isdir(full_path) and os.access(full_path, os.W_OK):
                writable_dirs.append(full_path)

writable_dirs

